import ErrorFallback from "./ErrorFallback";
import type { CanvasAreaProps } from "./types";

function CanvasArea({
  isReady,
  isGenerating,
  availability,
  progress,
  canvas,
  error,
  onDismissError,
}: CanvasAreaProps) {
  return (
    <main className="canvas-wrap">
