          className={`generated-canvas ${isGenerating ? "is-generating" : ""}`}
          aria-live="polite"
          dangerouslySetInnerHTML={{ __html: canvas }}
        />
      )}
      {error && isReady && (
        <div className="inline-error">
          {error}{" "}
          <button type="button" onClick={onDismissError}>
            Dismiss
          </button>
        </div>
      )}
    </main>
  );
}

